# Try identifying connected components and see if that explains the output

def find_components(grid):
    """Find all connected components of non-background cells"""
    hi, wi = len(grid), len(grid[0])
    visited = set()
    components = []

    for i in range(hi):
        for j in range(wi):
            if grid[i][j] != 1 and (i,j) not in visited:  # 1 is background in demo 2
                comp = []
                stack = [(i, j)]
                val = grid[i][j]

                while stack:
                    ri, rj = stack.pop()
                    if (ri, rj) in visited:
                        continue
                    visited.add((ri, rj))
                    comp.append((ri, rj))

                    # 8-connectivity
                    for di in [-1, 0, 1]:
                        for dj in [-1, 0, 1]:
                            if di == 0 and dj == 0:
                                continue
                            ni, nj = ri + di, rj + dj
                            if 0 <= ni < hi and 0 <= nj < wi:
                                if grid[ni][nj] == val and (ni, nj) not in visited:
                                    stack.append((ni, nj))

                components.append((val, comp))

    return components

